// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw :
JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim() ).filter(Boolean);
const headers = lines[0].split(",").map( h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza minimo para numero
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const clientes = $json.body.clientes || [];

const resultados = clientes.map(cliente => {

  const saldo_num = Number(
    cliente.saldo
      .replace("R$", "")
      .replace(/\./g, "")
      .replace(",", ".")
      .trim()
  );

  let recomendacao = {};

  switch (cliente.perfil) {

    case "Conservador":
      recomendacao = {
        perfil: "Conservador",
        produto: "CDB Liquidez Diária",
        minimo: 1000,
        rentabilidade: "12.5%",
      };
      break;

    case "Moderado":
      recomendacao = {
        perfil: "Moderado",
        produto: "CDB Prefixado",
        minimo: 1000,
        rentabilidade: "14.0%",
      };
      break;

    case "Arrojado":
      recomendacao = {
        perfil: "Arrojado",
        produto: "ETF de Ações",
        minimo: 5000,
        rentabilidade: "Potencial elevado",
      };
      break;
  }

  recomendacao.motivo =
    saldo_num >= recomendacao.minimo
      ? "saldo_ok"
      : "saldo_insuficiente";

  const mensagens = [
    `Olá ${cliente.nome}! Pelo seu perfil (${cliente.perfil}), uma boa opção é **${recomendacao.produto}** (mínimo R$ ${recomendacao.minimo.toLocaleString("pt-BR")}). Com seu saldo atual (${cliente.saldo}), você ${
      saldo_num >= recomendacao.minimo ? "já consegue" : "ainda não consegue"
    } investir. Rentabilidade: ${recomendacao.rentabilidade}.`,

    `Oi ${cliente.nome}! Recomendação para perfil ${cliente.perfil}: **${recomendacao.produto}** (mínimo R$ ${recomendacao.minimo.toLocaleString("pt-BR")}). Seu saldo (${cliente.saldo}) ${
      saldo_num >= recomendacao.minimo ? "já atende" : "não atende"
    } o mínimo. Rentabilidade: ${recomendacao.rentabilidade}.`,

    `${cliente.nome}, indo direto ao ponto: para o perfil ${cliente.perfil}, sugerimos **${recomendacao.produto}** (mínimo R$ ${recomendacao.minimo.toLocaleString("pt-BR")}). Você tem ${cliente.saldo}, então ${
      saldo_num >= recomendacao.minimo ? "dá para aplicar" : "ainda falta saldo"
    }. Rentabilidade: ${recomendacao.rentabilidade}.`
  ];

  const mensagem_escolhida = mensagens[1];

  return {
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo_texto: cliente.saldo,
    saldo_num,
    recomendacao,
    mensagens,
    mensagem_escolhida
  };

});

return [
  {
    json: {
      ok: true,
      total_clientes: clientes.length,
      total_investimentos: 3,
      resultados
    }
  }
];

const resultados = ($json.resultados || []).slice(0, 2);

function parseBRL(valor) {
  if (!valor) return 0;

  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();

  const n = Number(s);

  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {

  const saldoNum =
    c.saldo_num ??
    parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {

      email: String(c.email || "").trim().toLowerCase(),

      nome: String(c.nome || "").trim(),

      perfil: c.perfil,

      saldo_texto: c.saldo_texto ?? c.saldo,

      saldo_num: saldoNum,

      recomendacao: c.recomendacao,

      motivo: c.motivo,

      mensagem_base:
        c.mensagem_escolhida ||
        c.mensagem ||
        "",

      copy_rules: {
        idioma: "pt-BR",

        tom: "amigável e profissional",

        tamanho: "curto (4-6 linhas)",

        evitar: [
          "promessas de ganho",
          "garantias",
          "linguagem agressiva"
        ]
      }
    }
  };
});

return out;

return items.map(item => {

  let resposta = item.json.output || item.json.text || item.json.response || "";

  // Remove markdown ```json ... ```
  resposta = String(resposta)
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  try {

    const parsed = JSON.parse(resposta);

    return {
      json: {
        ok: true,
        to:  parsed.email || "",
        subject: parsed.subject || "",
        text_body: parsed.text_body || "",
        html_body: parsed.html_body || ""
      }
    };

  } catch (error) {

    return {
      json: {
        ok: false,
        to: item.json.email || "",
        erro: "JSON inválido retornado pela IA",
        resposta_original: resposta
      }
    };

  }

});
